    { "text": "Für Angehörige soll es eine Option geben, einen Gastzugriff zu beantragen, um temporären Zugriff auf bestimmte Profilinformationen zu erhalten.", "targetType": "requirement", "rationale": "dies folgt aus REQ-25, um Angehörigen eine flexiblere Nutzung zu ermöglichen." },
    { "text": "Die App soll eine Feedback-Funktion bieten, über die Nutzer Rückmeldungen zu den Profilinhalten geben können.", "targetType": "requirement", "rationale": "dies unterstützt die Informationstiefe gemäß REQ-01 und fördert die Qualität der Wissensbereitstellung." },
    { "text": "Auf der Profilübersichtsseite soll eine Filteroption vorhanden sein, um Profile nach speziellen Kriterien (z.B. Hobbys, Altersgruppen) anzuzeigen.", "targetType": "requirement", "rationale": "dies folgt aus REQ-07, um die Benutzersuche zu optimieren." },
    { "text": "Die Kommunikationsseiten sollen die Möglichkeit bieten, direkt mit anderen Nutzern über einen Chat oder Messaging-Funktion zu kommunizieren.", "targetType": "requirement", "rationale": "dies könnte die Interaktion zwischen Bewohnern und Betreuern gemäß REQ-48 fördern." },
    { "text": "Die About-Me-Seite soll ein Feld für Notizen haben, damit Nutzer eigene Gedanken oder Erinnerungen hinzufügen können.", "targetType": "requirement", "rationale": "dies unterstützt REQ-11 und macht die Profile individueller." },
    { "text": "Die App soll eine Option für anonyme Rückmeldungen zu No-Gos anbieten, um ehrliches Feedback von Nutzern zu ermöglichen.", "targetType": "requirement", "rationale": "dies folgt aus REQ-21, um wichtige Informationen zu sammeln, ohne die Nutzer zu belasten." },
    { "text": "Die App soll eine Übersicht über anstehende Termine und Erinnerungen für wichtige Daten wie Arztbesuche bieten.", "targetType": "requirement", "rationale": "dies erweitert den Kalenderansatz in REQ-24 und unterstützt die Nutzerorganisation." },
    { "text": "Die Detailansicht eines Profils soll einen Abschnitt für ein Video über das persönliche Leben oder die Kommunikation des Bewohners enthalten.", "targetType": "requirement", "rationale": "dies folgt aus REQ-17, um persönliche Interaktionen weiter zu fördern." },
    { "text": "Es sollen Schulungsmaterialien für neue Mitarbeiter in einem speziellen Bereich der App bereitgestellt werden.", "targetType": "requirement", "rationale": "dies unterstützt das Ziel aus REQ-02 und verbessert die Einarbeitung." },
    { "text": "Die App soll eine Funktion zur Planung und Organisation von Gruppenaktivitäten aufnehmen, um die soziale Interaktion zu stärken.", "targetType": "requirement", "rationale": "dies könnte Unterstützungsziele aus REQ-01 und REQ-48 fördern." },
    { "text": "Die No-Go-Seite soll auch optische Signale enthalten, die Nutzer über zu vermeidende Verhaltensweisen informieren.", "targetType": "requirement", "rationale": "dies ergänzt REQ-21 durch eine visuelle Unterstützung, die das Verständnis erleichtert." },
    { "text": "Die App soll eine Anforderung zur Zustimmung der Nutzer für die Verarbeitung von Kommunikationsdaten im Rahmen von Datenschutzbestimmungen integrieren.", "targetType": "requirement", "rationale": "dies folgt aus REQ-32, um die Datenschutzrichtlinien zu unterstützen." },
    { "text": "Die Einstellungen-Seite soll eine Sicherheitsoption enthalten, um die Nutzerdaten bei Bedarf vollständig zu anonymisieren.", "targetType": "requirement", "rationale": "dies unterstützt Datenschutzanliegen aus REQ-32." },
    { "text": "Die App soll eine Funktion zum Exportieren von Profilinformationen in ein gängiges Format anbieten, um die Daten außerhalb der App nutzen zu können.", "targetType": "requirement", "rationale": "dies könnte die Nutzung und den Austausch von Informationen gemäß REQ-01 unterstützen." },
    { "text": "Die App soll regelmäßig Sicherheitsupdates erhalten, um den Schutz sensibler Nutzerdaten zu gewährleisten.", "targetType": "requirement", "rationale": "dies folgt aus den Punkten bezüglich Datenschutz und Sicherheit in REQ-32 und REQ-35." }
  ]
}"
